## Plotting Trends of daily Close Price

::: text-justify
Below I start with designing the building blocks for the visualizations. By building blocks, here I concretely mean 'embedding' a `ggplot2` like theme as I am a fan of the overall layout (I can't be the only one). `create_ggplot_theme()` function below is a nifty way to set a modular/reusable set of values as a dictionary to then be used as arguments for the theme in both `plot_stock_facets()` and `plot_single_comparison()`
:::

::: {#build-plot-structures .cell execution_count=5}
``` {.python .cell-code}
def create_ggplot_theme():
    """create a ggplot2 theme_minimal() equivalent for plotly"""
    return {
    'template': 'plotly_white',
    'font': {'family': 'Merriweather, Georgia, serif', 'size': 12, 'color': '#333333'},
    'title': {
        'x': 0.5, 
        'font': {'family': 'Merriweather, Georgia, serif', 'size': 16, 'color': '#333333', 'weight': 'bold'}
    },
    'showlegend': True,
    'legend': {
        'orientation': 'h',
        'yanchor': 'bottom',
        'y': -0.2,
        'xanchor': 'center',
        'x': 0.5,
        'bgcolor': 'rgba(0,0,0,0)',
        'bordercolor': 'rgba(0,0,0,0)'
    },
    'margin': {'l': 60, 'r': 40, 't': 60, 'b': 80},
    'plot_bgcolor': '#F8F8F8',
    'paper_bgcolor': '#F8F8F8'
    }

def update_axes_theme(fig):
    """apply ggplot2-style axis formatting"""
    fig.update_xaxes(
        title_text="", # hid x axis
        showgrid=True,
        gridwidth=0.5,
        gridcolor='#E5E5E5',
        showline=True,
        linewidth=0.5,
        linecolor='#CCCCCC',
        mirror=False,
        ticks='outside',
        tickcolor='#CCCCCC',
        title_font={'size': 12, 'color': '#666666'}
    )

    fig.update_yaxes(
      title={
        'text': 'Close Price',
        'standoff': 10, # distance from y axis
        'font': {'size': 12, 'family': 'Merriweather, Georgia, serif', 'color': '#666666'}
        },
        showgrid=True,
        gridwidth=0.5,
        gridcolor='#E5E5E5',
        showline=False,
        zeroline=False,
        ticks='outside',
        tickcolor='#CCCCCC',
        title_font={'size': 12, 'color': '#666666'},
        tickformat='$,.0f'
    )

    return fig

def plot_single_comparison(data, title="Stock Price Comparison"):
    """
    create a single plot with all stocks for comparison
    """

    # color palette
    colors = ['#1f77b4', '#ff7f0e', '#2ca02c', '#d62728', '#9467bd', '#8c564b']

    fig = go.Figure()

    tickers = sorted(data['ticker'].unique().to_list())

    for i, ticker in enumerate(tickers):
        ticker_data = data.filter(pl.col('ticker') == ticker).sort('Date')

        fig.add_trace(
            go.Scatter(
                x=ticker_data['Date'].to_list(),
                y=ticker_data['Close'].to_list(),
                mode='lines',
                name=ticker,
                line=dict(color=colors[i % len(colors)], width=2),
                hovertemplate='<b>%{fullData.name}</b><br>' +
                            'Date: %{x}<br>' +
                            'Close: $%{y:.2f}<extra></extra>'
            )
        )

    # apply theme
    theme = create_ggplot_theme()
    fig.update_layout(**theme)
    fig.update_layout(
        title=title,
        xaxis_title="Date",
        yaxis_title="Close Price",
        height=500
    )

    fig = update_axes_theme(fig)

    # center and bolden title
    fig.update_layout(
        title={
            'text': title,
            'x': 0.5,
            'xanchor': 'center',
            'font': {'size': 16, 'family': 'Merriweather, Georgia, serif', 'color': '#333333', 'weight': 'bold'}
        }
    )
    return fig

# single comparison plot
comparison_chart = plot_single_comparison(
    pl_results,
    title="Stock Price Comparison Overall (6 Months)"
)

# display the charts
comparison_chart.show()
