::: text-justify
Overall, and despite the dips and volatility, and while a few grew more than others, all 6 stocks have risen in value over the trailing 6 month period. Speaking of volatility, let's gather more stats around stock price evolution and tease out more insights overall.
:::

::: {#cell-summary-table .cell execution_count=7}
``` {.python .cell-code}
most_recent_date = pl_results.select('Date').max().item()

summary_stats = (
  pl_results
  .group_by(
    pl.col('ticker')
    )
  .agg(
    volatility_std = pl.col('Close').std(),
    # coefficient of variation (volatility relative to price)
    cv = (pl.col('Close').std() / pl.col('Close').mean()).alias('cv_percent'),
    average_price = pl.col('Close').mean(),
    # last month rolling window average
    average_trailing_1mo = pl.col('Close')
    .filter(
      pl.col('Date') >= (most_recent_date - timedelta(days=30)))
      .mean(),
    average_trailing_2mo = pl.col('Close')
    .filter(
      pl.col('Date') >= (most_recent_date - timedelta(days=60)))
      .mean()
    )
  .with_columns(
    volatility_rank = pl.col('cv').rank(descending=True)
    )
)

# pull svgs to then render as markdown instead of display plain ticker text
def svg_to_html(ticker, width=80, height=60):
    """convert SVG file to inline HTML for gt tables"""
    # map tickers to filenames
    svg_files = {
        'AAPL' : 'apple-svgrepo-com.svg',
        'GOOGL': 'google-2015-logo-svgrepo-com.svg',
        'NFLX' : 'netflix-svgrepo-com.svg', 
        'NVDA' : 'nvidia-logo-svgrepo-com.svg',
        'MSFT' : 'microsoft-logo-svgrepo-com.svg',
        'TSLA' : 'tesla-9-logo-svgrepo-com.svg'
    }

    if ticker in svg_files:
        with open(svg_files[ticker], 'r') as f:
            svg_content = f.read()

        return f'''<div style="width:{width}px;height:{height}px;overflow:hidden;display:flex;align-items:center;justify-content:center;">
                     <div style="transform:scale(0.1);transform-origin:center;">{svg_content}</div>
                   </div>'''
    else:
        return ticker # else fallback to plain ticker text

# render logo column, select needed columns, and sort on volatility rank
stock_summary = (
  summary_stats.with_columns(
    logo = pl.col('ticker').map_elements(
        lambda x: svg_to_html(x), 
        return_dtype=pl.Utf8
        )
    )
    .select(
      'logo','volatility_rank', 'volatility_std', 'cv', 
      'average_price', 'average_trailing_1mo', 'average_trailing_2mo'
      )
    .sort('volatility_rank')
    )

# gt output with logo mkdown-rendered and more general styling
styled_stock_summary = (
    gt_nyt_custom(
        stock_summary,
        title = "On Volatility & Averages",
        subtitle = "",
        first_10_rows_only=True
    )
    .fmt_markdown(columns='Logo')
    .fmt_percent(columns='Cv')              
    .fmt_integer(columns='Volatility Rank') 
    .tab_style(
        style=style.text(color="black", size = 16, align = 'center'),
        locations=loc.column_labels()
    )
    .tab_spanner(
        label = md('**Volatility Stats**'),
        columns = ['Volatility Std', 'Cv', 'Volatility Rank']  
    )
    .tab_spanner(
        label = md('**Average Closing Price**'),
        columns = ['Average Price', 'Average Trailing 2Mo', 'Average Trailing 1Mo'] 
    )
    .tab_style(
        style=style.text(color= '#2e8b57', weight = 'bold'),
        locations=gt.loc.body(
          columns = ['Volatility Std', 'Cv', 'Volatility Rank'],
          rows = (pl.col('Volatility Rank') == 6)
          )
    )
    .tab_style(
        style=style.text(color= '#8b1a1a', weight = 'bold'),
        locations=gt.loc.body(
          columns = ['Volatility Std', 'Cv', 'Volatility Rank'],
          rows = (pl.col('Volatility Rank') == 1)
          )
    )
    .tab_source_note(
      source_note=md("""*Coef. of Variation (CV) = σ/μ × 100%, where σ is standard deviation and μ is the mean.<br>
      **Volatility Rank: Simple Rank based on Coef. of Variation (1 = most volatile, 6 = least volatile)""")
      )
    .cols_label(**{
        "Logo": "",
        "Volatility Std": "Std. Deviation", 
        "Cv": "*Coef. of Variation",
        "Volatility Rank": "**Volatility Rank"
    })
)

